.dashboard-cards {
  display: grid;
  gap: 0.75rem;
  grid-template-columns: repeat(auto-fit, minmax(10rem, 1fr));
}
.metric-card {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--r-2);
  display: grid;
  gap: 0.25rem;
  min-width: 0;
  padding: 0.875rem 1rem;
}
.metric-card > * {
  min-width: 0;
}
.dashboard-money {
  display: grid;
  gap: 0.5rem;
  margin-top: 1rem;
}
.dashboard-money-currency > .eyebrow {
  margin-bottom: 0.375rem;
}
.metric-card strong {
  font-size: var(--text-display);
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}
.dashboard-attention ul {
  display: grid;
  gap: 0.375rem;
  list-style: none;
  margin: 0.5rem 0 0;
  padding: 0;
}
.attention-item a {
  align-items: center;
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--r-2);
  color: var(--theme-text-primary);
  display: flex;
  gap: 0.625rem;
  justify-content: space-between;
  padding: 0.625rem 0.875rem;
  text-decoration: none;
}
.attention-item a:hover {
  border-color: var(--theme-border-strong);
}
.attention-item strong {
  font-variant-numeric: tabular-nums;
}
.attention-item.is-warn a {
  border-color: var(--theme-warning);
}
.attention-item.is-warn strong {
  color: var(--theme-warning);
}
.attention-item .attention-label {
  flex: 1;
}
.attention-item .attention-cta {
  color: var(--theme-accent);
  font-size: var(--type-dense);
  font-weight: 600;
  margin-left: auto;
  white-space: nowrap;
}
.attention-item a:hover .attention-cta {
  text-decoration: underline;
}
.dashboard-activity {
  list-style: none;
  margin: 0.5rem 0 0;
  padding: 0;
}
.dashboard-activity li {
  align-items: baseline;
  display: flex;
  gap: 0.75rem;
  padding: 0.375rem 0;
}
.dashboard-activity li + li,
.dashboard-row + .dashboard-row,
.dashboard-list li + li .dashboard-row {
  border-top: 1px solid var(--theme-border-subtle);
}
.dashboard-activity-event {
  color: var(--theme-text-primary);
  min-width: 0;
}
.dashboard-activity-code {
  font-family: var(--font-mono);
  font-size: var(--type-body);
  white-space: nowrap;
}
.dashboard-activity time {
  color: var(--theme-text-muted);
  font-size: var(--type-dense);
  margin-left: auto;
  white-space: nowrap;
}
.dashboard-attention-clear {
  color: var(--theme-text-secondary);
  margin: 0.375rem 0 0;
}
.dashboard-empty {
  background: var(--theme-surface-panel);
  border: 1px dashed var(--theme-border-strong);
  border-radius: var(--r-2);
  padding: 2rem;
  text-align: center;
}
.dashboard-empty p {
  color: var(--theme-text-secondary);
  margin: 0;
}
.dashboard-list {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--r-2);
}
.dashboard-list-head {
  align-items: center;
  border-bottom: 1px solid var(--theme-border-subtle);
  display: flex;
  justify-content: space-between;
  padding: 0.625rem 1rem;
}
.dashboard-list-head h2 {
  font-size: var(--type-micro);
  margin: 0;
}
.dashboard-list-head a {
  color: var(--theme-accent);
  font-weight: 600;
  text-decoration: none;
}
.dashboard-list ul {
  list-style: none;
  margin: 0;
  padding: 0;
}
.dashboard-row {
  align-items: center;
  color: var(--theme-text-primary);
  display: grid;
  gap: 0.75rem;
  grid-template-columns: minmax(8rem, 1.4fr) auto minmax(6rem, 1fr) auto;
  padding: 0.5rem 1rem;
  text-decoration: none;
}
.dashboard-row-code {
  color: var(--theme-text-muted);
  font-family: var(--font-mono);
  font-size: var(--type-dense);
  white-space: nowrap;
}
.dashboard-row-name {
  font-weight: 600;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.dashboard-row-client {
  color: var(--theme-text-secondary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.dashboard-continue {
  align-items: baseline;
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-left: 3px solid var(--theme-accent);
  border-radius: var(--r-2);
  color: var(--theme-text-primary);
  display: grid;
  gap: 0.125rem 1rem;
  grid-template-columns: minmax(0, 1fr) auto;
  padding: 0.875rem 1rem;
  text-decoration: none;
}
.dashboard-continue:hover {
  border-color: var(--theme-accent);
  border-left-color: var(--theme-accent);
}
.dashboard-continue-name {
  font-size: var(--type-workshop);
  font-weight: 600;
  grid-column: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.dashboard-continue-meta {
  color: var(--theme-text-secondary);
  grid-column: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.dashboard-continue-cta {
  align-self: center;
  color: var(--theme-accent);
  font-weight: 600;
  grid-column: 2;
  grid-row: 2 / 4;
}
@media (max-width: 640px) {
  .dashboard-continue {
    grid-template-columns: 1fr;
  }
  .dashboard-continue-cta {
    grid-column: 1;
    grid-row: auto;
  }
}
.status-chip,
.production-chip,
.production-chip-danger {
  border-radius: var(--r-2);
  display: inline-block;
  font-size: var(--type-micro);
  font-weight: 600;
  line-height: 1.5;
  padding: 0.125rem 0.625rem;
}
button.production-chip {
  border: 0;
}
button.production-chip:hover {
  filter: brightness(0.95);
}
.production-chip.status-released {
  background: var(--theme-info-soft);
  color: var(--theme-accent-deep);
}
.production-chip.status-in_progress,
.production-chip.delivery-on_route,
.status-chip[data-status="quoted"],
.status-chip[data-status="priced"] {
  background: var(--theme-accent-soft);
  color: var(--theme-accent-ink);
}
.production-chip.status-hold,
.production-chip.is-warn,
.status-chip[data-status="frozen"] {
  background: var(--theme-warning-soft);
  color: var(--theme-warning);
}
.production-chip.status-completed,
.production-chip.status-installed,
.production-chip.is-ready,
.production-chip.delivery-delivered,
.status-chip[data-status="approved"],
.status-chip[data-status="in_production"],
.status-chip[data-status="production"] {
  background: var(--theme-success-soft);
  color: var(--theme-success);
}
.production-chip.status-dispatched,
.status-chip[data-status="completed"] {
  background: var(--theme-accent-soft);
  color: var(--theme-accent-strong);
}
.production-chip.delivery-scheduled,
.status-chip[data-status="evaluated"],
.status-chip[data-status="pending"] {
  background: var(--theme-info-soft);
  color: var(--theme-info);
}
.production-chip.delivery-failed,
.status-chip[data-status="cancelled"],
.status-chip[data-status="declined"],
.status-chip[data-status="revoked"] {
  background: var(--theme-danger-soft);
  color: var(--theme-danger);
}
.production-chip-danger {
  background: var(--theme-danger-soft);
  color: var(--theme-danger);
}
.status-chip[data-status="draft"] {
  background: var(--theme-surface-card);
  border: 1px solid var(--theme-border-strong);
  color: var(--theme-text-secondary);
}
.settings-group {
  margin-top: 1.25rem;
}
.settings-group__title {
  border-bottom: 1px solid var(--theme-border-subtle);
  font-size: var(--type-body);
  font-weight: 600;
  margin: 0 0 0.75rem;
  padding-bottom: 0.5rem;
}
.settings-grid {
  display: grid;
  gap: 0.75rem;
  grid-template-columns: repeat(auto-fit, minmax(16rem, 1fr));
}
.settings-card {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--r-2);
  padding: 0.875rem 1rem;
}
.settings-card h2,
.settings-card h3 {
  font-size: var(--type-micro);
  margin: 0 0 0.625rem;
}
.settings-list {
  display: grid;
  gap: 0.5rem;
  margin: 0;
}
.settings-plain {
  list-style: none;
  padding: 0;
}
.settings-row {
  align-items: baseline;
  display: flex;
  justify-content: space-between;
  gap: 1rem;
}
.settings-row dt {
  color: var(--theme-text-secondary);
  margin: 0;
}
.settings-row dd {
  margin: 0;
  text-align: right;
}
.settings-role {
  color: var(--theme-text-secondary);
}
.settings-mono {
  font-family: var(--font-mono);
  font-size: var(--type-dense);
}
.settings-branding-preview {
  align-items: center;
  border: 1px dashed var(--theme-border-subtle);
  border-radius: var(--r-2);
  display: flex;
  justify-content: center;
  margin: 0 0 0.75rem;
  min-height: 4rem;
  padding: 0.5rem;
}
.settings-branding-logo {
  max-height: 3.5rem;
  max-width: 100%;
  object-fit: contain;
}
.payments-form {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 10px;
  margin-top: 10px;
}
.payments-form label {
  display: grid;
  gap: 4px;
  font-size: var(--text-s, 12px);
  color: var(--ink-muted);
}
.payments-form-wide {
  grid-column: 1 / -1;
}
.payments-form-actions {
  grid-column: 1 / -1;
  display: flex;
  gap: 8px;
}
.payments-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 10px;
  font-size: var(--text-s, 13px);
}
.payments-table th,
.payments-table td {
  text-align: left;
  padding: 6px 8px;
  border-bottom: 1px solid var(--border, #e0deda);
}
.payments-table .num {
  text-align: right;
  font-family: var(--font-mono, monospace);
}
.payments-voided td {
  opacity: 0.55;
}
.file-input-hidden {
  display: none;
}
.file-field {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.file-field__name {
  color: var(--theme-text-secondary);
  font-size: var(--text-s, 12px);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.settings-theme {
  border: 1px solid var(--theme-border-strong);
  border-radius: var(--r-2);
  display: inline-flex;
  overflow: hidden;
}
.settings-theme-option {
  background: transparent;
  border: 0;
  color: var(--theme-text-secondary);
  padding: 0.375rem 0.875rem;
}
.settings-theme-option[data-active="true"] {
  background: var(--theme-accent);
  color: var(--theme-surface-panel);
}
.settings-hint {
  color: var(--theme-text-secondary);
  margin: 0 0 0.625rem;
}
.settings-links {
  display: flex;
  gap: 1.25rem;
}
.settings-links a {
  color: var(--theme-accent);
  font-weight: 600;
  text-decoration: none;
}
.rail-toggle {
  display: none;
}
.rail-scrim {
  background: transparent;
  border: none;
  cursor: default;
  display: none;
  inset: 0;
  padding: 0;
  position: fixed;
  z-index: var(--z-popover);
}
@media (max-width: 1024px) {
  .rail-toggle {
    align-items: center;
    border: none;
    border-radius: var(--radius-md);
    display: inline-flex;
    font-size: var(--type-workshop);
    height: 32px;
    justify-content: center;
    padding: 0;
    width: 32px;
  }
  .rail-scrim {
    display: block;
    visibility: hidden;
  }
  .app-shell.rail-open .rail-scrim {
    background: rgba(15, 15, 14, 0.45);
    visibility: visible;
  }
  .app-rail {
    box-shadow: none;
    left: 0;
    position: fixed;
    top: 0;
    transform: translateX(-105%);
    transition:
      transform 0.18s ease,
      visibility 0.18s ease;
    visibility: hidden;
    z-index: var(--z-drawer);
  }
  .app-shell.rail-open .app-rail {
    box-shadow: var(--e2);
    transform: translateX(0);
    visibility: visible;
  }
}
@media (min-width: 1025px) {
  .app-shell[data-studio] .app-rail {
    align-items: stretch;
    padding-inline: 0;
    width: 4rem;
  }
  .app-shell[data-studio] .app-rail__brand {
    padding-inline: 0;
    text-align: center;
  }
  .app-shell[data-studio] .app-rail__brand .brand {
    font-size: 0;
    justify-content: center;
  }
  .app-shell[data-studio] .org-switcher,
  .app-shell[data-studio] .rail-group__title,
  .app-shell[data-studio] .app-rail__identity,
  .app-shell[data-studio] .rail-item > span {
    display: none;
  }
  .app-shell[data-studio] .rail-item {
    border-left-width: 2px;
    border-radius: var(--radius-md);
    justify-content: center;
    margin-inline: auto;
    padding-inline: 0;
    width: 2.5rem;
  }
  .app-shell[data-studio] .rail-item__icon {
    height: 18px;
    width: 18px;
  }
}
@media (max-width: 640px) {
  .app-topbar {
    gap: 0.5rem;
  }
  .ui-page-header__row {
    flex-direction: column;
    gap: var(--space-2);
  }
  .ui-page-header__actions {
    flex-wrap: wrap;
    width: 100%;
  }
  .attention-item a {
    flex-wrap: wrap;
  }
  .attention-item .attention-cta {
    margin-left: 0;
  }
  .topbar-search span {
    display: none;
  }
  .workspace {
    padding: var(--space-3) var(--space-2);
  }
  .dashboard-cards {
    grid-template-columns: 1fr;
  }
  .metric-card strong {
    font-size: var(--text-title);
  }
  .dashboard-row {
    gap: 0.125rem 0.5rem;
    grid-template-columns: minmax(0, 1fr) auto;
    padding-block: 0.625rem;
  }
  .dashboard-row-name {
    grid-column: 1;
    grid-row: 1;
  }
  .dashboard-row .status-chip {
    grid-column: 2;
    grid-row: 1;
    justify-self: end;
  }
  .dashboard-row-client {
    grid-column: 1;
    grid-row: 2;
  }
  .dashboard-row-code {
    grid-column: 2;
    grid-row: 2;
    justify-self: end;
  }
  .dashboard-activity li {
    flex-wrap: wrap;
    row-gap: 0.125rem;
  }
  .onboarding {
    padding: var(--space-4) var(--space-2);
  }
}
.jobs-filter {
  min-width: 10rem;
}
.jobs-list {
  grid-column: 1 / -1;
}
.jobs-list {
  display: grid;
  gap: 0.5rem;
  list-style: none;
  margin: 0;
  padding: 0;
}
.job-row {
  align-items: center;
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--r-2);
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem 1rem;
  padding: 0.625rem 0.875rem;
}
.job-row-main {
  align-items: center;
  display: flex;
  flex: 1;
  gap: 0.625rem;
