}
.clients-desk {
  align-items: start;
  display: grid;
  gap: 1rem;
  grid-template-columns: minmax(16rem, 22rem) minmax(0, 1fr);
}
.clients-list {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--r-2);
  padding: 0.75rem;
}
.clients-list > ul {
  display: grid;
  gap: 0.25rem;
  list-style: none;
  margin: 0.5rem 0 0;
  padding: 0;
}
.clients-row {
  align-items: start;
  background: none;
  border: 1px solid transparent;
  border-radius: var(--r-2);
