  letter-spacing: 0.04em;
  text-transform: uppercase;
}
.clients-facts dd {
  margin: 0.125rem 0 0;
  white-space: pre-wrap;
}
.clients-projects {
  list-style: none;
  margin: 0.5rem 0 0;
  padding: 0;
}
.clients-project-row {
  align-items: center;
  color: var(--theme-text-primary);
  display: grid;
  gap: 0.75rem;
  grid-template-columns: auto minmax(8rem, 1fr) auto auto;
  padding: 0.5rem 0;
