  align-items: center;
  gap: var(--space-4px);
}
.ui-code__button {
  background: transparent;
  border: 1px solid transparent;
  padding: var(--space-2px);
  color: var(--interactive);
}
.ui-code__fallback {
  display: grid;
  gap: var(--space-4px);
}
.ui-unknown,
.ui-unknown__cause {
  color: var(--text-secondary);
}
.ui-unknown__action {
