  border-inline-start: 2px solid var(--interactive);
}
.ui-data-table tr:hover {
  background: var(--surface-hover);
}
.ui-table-selection {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-8px);
  padding: var(--space-4px);
  border-block: 1px solid var(--border-default);
}
.is-virtual .ui-data-table td {
  white-space: nowrap;
  max-width: 24rem;
  overflow: hidden;
  text-overflow: ellipsis;
}

.projects-page {
  /* Match .dashboard's workspace width — 96rem left ~190px dead rails on each
   * side of a 1920 viewport while master-detail panes could use them. */
  max-width: 120rem;
  margin-inline: auto;
