  border-radius: var(--radius-sm);
}
.projects-page textarea {
  min-height: 5rem;
  resize: vertical;
}
.projects-page :focus-visible {
  outline: 2px solid var(--theme-accent);
  outline-offset: 2px;
}
.projects-page a {
  color: var(--theme-accent);
}
.projects-page [role="alert"] {
