.viewport-menu {
  border: 1px solid var(--theme-border-subtle);
  bottom: calc(100% + 6px);
  box-shadow: var(--shadow-pop);
  flex-direction: column;
  left: 0;
  min-width: 10.5rem;
  padding: 3px;
  position: absolute;
}
.viewport-menu__item {
  background: transparent;
  border: none;
  border-radius: var(--radius-sm);
  color: var(--theme-text-primary);
  font: inherit;
  padding: 0.4rem 0.6rem;
  text-align: left;
}
.viewport-menu__item:hover:not(:disabled) {
  background: var(--theme-accent-soft);
}
.viewport-menu__item:disabled {
  color: var(--theme-text-muted);
  cursor: default;
}
.viewport-status {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-md);
  bottom: 0.75rem;
  color: var(--theme-text-muted);
  font-family: var(--font-mono);
  font-size: var(--type-dense);
  padding: 0.3rem 0.55rem;
  position: absolute;
  right: 0.75rem;
  z-index: var(--z-base);
}
.product-front-svg {
  display: block;
  width: 100%;
}
.front-module {
  cursor: pointer;
}
.member {
  vector-effect: non-scaling-stroke;
}
.front-module .member-frame {
  stroke-width: 4;
}
.front-module.is-selected .member-frame {
  stroke: var(--theme-accent);
  stroke-width: 6;
}
.front-module.has-error .member-frame {
  stroke: var(--theme-danger);
  stroke-width: 6;
}
.front-module.has-warning .member-frame {
  stroke: var(--theme-warning);
  stroke-width: 6;
}
.module-opening {
  fill: none;
}
.module-opening--lite {
  fill: var(--theme-glass-pane);
}
.member-sash {
  stroke-width: 2;
}
.member-mullion,
.member-coupler,
.member-threshold {
  stroke-width: 2.5;
}
.product-front-svg {
  --finish-bead-color: var(--member-pvc-edge);
  --finish-handle-color: var(--theme-accent-ink);
}
.member-bead {
  fill: none;
  stroke: var(--finish-bead-color, var(--member-pvc-edge));
  stroke-width: 1.4;
  vector-effect: non-scaling-stroke;
}
.module-glass {
  fill: var(--theme-glass-pane);
  stroke: var(--theme-border-subtle);
  stroke-width: 1.4;
  vector-effect: non-scaling-stroke;
}
.glass-sheen {
  stroke: var(--member-pvc-highlight);
  stroke-width: 7;
  opacity: 0.75;
}
.bay-panel {
  fill: var(--member-panel-fill);
  stroke: var(--member-panel-edge);
  stroke-width: 1.6;
  vector-effect: non-scaling-stroke;
}
.handle-lever line,
.handle-lever path {
  fill: none;
  stroke: var(--finish-handle-color, var(--theme-accent-ink));
  stroke-width: 1.5;
  vector-effect: non-scaling-stroke;
}
.handle-lever .handle-datum-flag {
  fill: none;
  stroke: var(--theme-danger);
  stroke-dasharray: 3 2;
  stroke-width: 1.6;
  vector-effect: non-scaling-stroke;
}
.handle-lever.is-datum-invalid line {
  stroke: var(--theme-danger);
}
.member-inner {
  fill: none;
  stroke-width: 1.1;
  opacity: 0.55;
  vector-effect: non-scaling-stroke;
}
.member-thermal-strip {
  opacity: 0.5;
}
.module-glass-ig {
  fill: none;
  stroke: var(--theme-text-muted);
  stroke-width: 1.2;
  opacity: 0.65;
  vector-effect: non-scaling-stroke;
}
.door-hinge {
  fill: var(--theme-border-subtle);
  stroke: var(--theme-text-muted);
  stroke-width: 1.2;
  vector-effect: non-scaling-stroke;
}
.module-bay {
  pointer-events: none;
}
.module-bay.bay-pickable {
  cursor: pointer;
  pointer-events: auto;
}
.bay-select-ring {
  fill: none;
  pointer-events: none;
  stroke: var(--theme-accent);
  stroke-dasharray: 42 20;
  stroke-width: 10;
  vector-effect: non-scaling-stroke;
}
.dim-run {
  pointer-events: none;
}
.dim-extension {
  stroke: var(--theme-border-subtle);
  stroke-width: 1.5;
  vector-effect: non-scaling-stroke;
}
.dim-line {
  stroke: var(--theme-text-muted);
  stroke-width: 1.5;
  vector-effect: non-scaling-stroke;
}
.dim-tick {
  stroke: var(--theme-text-secondary);
  stroke-width: 2.6;
  vector-effect: non-scaling-stroke;
}
.opening-glyph polyline,
.opening-glyph line,
.opening-glyph path {
  stroke: var(--theme-text-secondary);
  stroke-width: 2.4;
  vector-effect: non-scaling-stroke;
}
.opening-glyph circle {
  fill: var(--theme-text-secondary);
}
.canvas-dim {
  fill: var(--theme-text-secondary);
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
}
.canvas-dim-wrap,
.add-handle {
  cursor: pointer;
}
.canvas-dim-hit {
  fill: var(--theme-surface-panel);
  opacity: 0;
  stroke: var(--theme-border-subtle);
  stroke-width: 1.5;
  transition: opacity 0.12s ease;
  vector-effect: non-scaling-stroke;
}
.canvas-dim-wrap:hover .canvas-dim-hit,
.canvas-dim-wrap:focus-visible .canvas-dim-hit,
.canvas-dim-wrap.is-active .canvas-dim-hit {
  opacity: 0.92;
}
.canvas-dim-wrap:hover .canvas-dim,
.canvas-dim:hover {
  fill: var(--theme-accent);
}
.canvas-dim.is-active {
  fill: var(--theme-accent-ink);
  font-weight: 500;
}
.canvas-dim-input {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-accent);
  color: var(--theme-text-primary);
  font-variant-numeric: tabular-nums;
  font-size: var(--type-title-m);
  padding: 0.15rem 0.3rem;
  text-align: center;
  width: 100%;
}
.add-handle circle {
  fill: var(--theme-surface-panel);
  stroke: var(--theme-border-subtle);
  stroke-width: 3;
  vector-effect: non-scaling-stroke;
}
.add-handle path {
  stroke: var(--theme-accent);
  stroke-width: 5;
  vector-effect: non-scaling-stroke;
}
.add-handle:hover circle,
.add-handle:focus circle {
  stroke: var(--theme-accent);
}
.detail-levels {
  display: flex;
  gap: var(--space-1);
  padding: var(--space-1);
  border: 1px solid var(--theme-border);
  border-radius: var(--radius-md);
  background: var(--theme-surface);
}
.opening-preview-label {
  position: absolute;
  top: var(--space-3);
  right: var(--space-3);
  max-width: 70%;
  color: var(--theme-accent-ink);
  background: var(--theme-bg-canvas);
  font-family: var(--font-sans);
  font-size: var(--type-dense);
  padding: var(--space-1) var(--space-2);
  z-index: var(--z-island);
}
.leaf-role-label {
  fill: var(--theme-text-secondary);
  font-family: var(--font-sans);
  font-size: var(--type-title-l);
}
.assembly-view-choices {
  position: absolute;
  top: var(--space-3);
  left: var(--space-3);
  color: var(--theme-text-secondary);
  background: var(--theme-bg-canvas);
  padding: var(--space-1) var(--space-2);
  display: flex;
  gap: var(--space-1);
  z-index: var(--z-island);
}
.assembly-view-choices button.assembly-face {
  border: 1px solid var(--theme-border);
  color: var(--theme-text-secondary);
  background: var(--theme-surface);
  border-radius: var(--radius-sm);
  padding: var(--space-1) var(--space-2);
  min-height: var(--control-height);
}
.assembly-view-choices button[aria-pressed="true"] {
  color: var(--theme-accent-ink);
  border-color: var(--theme-accent);
}
.product-front-svg.is-exterior text {
  transform: scaleX(-1);
  transform-box: fill-box;
  transform-origin: center;
}
.product-front-svg.is-exterior .handle-lever {
  display: none;
}
.product-front-svg.is-exterior .module-bay--door .handle-lever {
  display: initial;
}
.detail-levels__btn {
  flex: 1;
  padding: var(--space-1) var(--space-2);
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--theme-text-muted);
  font: inherit;
  font-size: var(--text-sm);
}
.detail-levels__btn:hover {
  color: var(--theme-text);
}
.detail-levels__btn.is-active {
  background: var(--theme-accent-soft);
  color: var(--theme-accent-ink);
  font-weight: 600;
}
.inspector-summary {
  padding: var(--space-3);
}
.inspector-summary__title {
  font-size: var(--text-sm);
  margin: 0 0 var(--space-2);
}
.inspector-summary__list {
  display: grid;
  gap: var(--space-2);
  margin: 0;
}
.inspector-summary__row {
  display: flex;
  justify-content: space-between;
  gap: var(--space-3);
}
.inspector-summary__row dt {
  color: var(--theme-text-muted);
  font-size: var(--text-sm);
}
.inspector-summary__row dd {
  font-size: var(--text-sm);
  margin: 0;
  text-align: right;
}
.tech-panel {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}
.tech-table {
  border-collapse: collapse;
  font-size: var(--text-xs);
  width: 100%;
}
.tech-table th {
  color: var(--theme-text-muted);
  font-weight: 500;
  text-align: left;
}
.tech-table th,
.tech-table td {
  border-bottom: 1px solid var(--theme-border-subtle);
  padding: var(--space-1) var(--space-2) var(--space-1) 0;
}
.tech-table td:not(:first-child) {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
  text-align: right;
}
.assembly-side {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  grid-area: side;
  min-height: 0;
  min-width: 0;
  overflow-y: auto;
}
.assembly-inspector {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
  padding: 0.6rem 0.75rem;
}
.assembly-inspector__header {
  align-items: center;
  display: flex;
  justify-content: space-between;
}
.assembly-inspector__header h4 {
  font-size: var(--type-workshop);
  margin: 0;
}
.assembly-hint {
  color: var(--theme-text-muted);
  font-size: var(--type-title-m);
  margin: 0;
}
.inspector-section {
  border-top: 1px solid var(--theme-border-subtle);
  display: contents;
}
.inspector-section > summary {
  color: var(--theme-text-muted);
  cursor: pointer;
  font-size: var(--type-dense);
  font-weight: 600;
  letter-spacing: 0.06em;
  list-style: none;
  margin-top: 0.4rem;
  padding: 0.3rem 0;
  text-transform: uppercase;
  user-select: none;
}
.inspector-section > summary::before {
  content: "▾";
  display: inline-block;
  margin-right: 0.35rem;
  transition: transform 0.12s ease;
}
.inspector-section:not([open]) > summary::before {
  transform: rotate(-90deg);
}
.inspector-section > summary::-webkit-details-marker {
  display: none;
}
.inspector-section:not([open]) > summary {
  margin-bottom: 0;
}
.inspector-section[open] > *:not(summary) {
  animation: none;
}
.opening-grid {
  display: grid;
  gap: 0.3rem;
  grid-template-columns: repeat(4, 1fr);
}
.opening-choice {
  background: var(--theme-bg-canvas);
  border: 1px solid var(--theme-border-subtle);
  padding: 0.15rem;
}
.opening-choice.is-active {
  border-color: var(--theme-accent);
  outline: 1px solid var(--theme-accent);
}
.opening-choice svg {
  display: block;
  width: 100%;
}
.opening-choice__frame {
  fill: var(--theme-glass-tint);
  stroke: var(--theme-text-secondary);
  stroke-width: 4;
}
.opening-choice [data-handle],
.opening-choice .opening-glyph polyline,
.opening-choice .opening-glyph line,
.opening-choice .opening-glyph path {
  stroke: var(--theme-text-primary);
  stroke-width: 3;
}
.inspector-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
}
.ghost-button {
  background: transparent;
  border: 1px solid var(--theme-border-subtle);
  color: var(--theme-text-primary);
  font-size: var(--type-title-m);
  padding: 0.3rem 0.55rem;
}
.ghost-button:hover:not(:disabled) {
  border-color: var(--theme-accent);
}
.ghost-button:disabled {
  border-style: dashed;
  color: var(--theme-text-muted);
  cursor: not-allowed;
  opacity: 0.5;
}
.ghost-button.is-danger:hover:not(:disabled) {
  border-color: var(--theme-danger);
  color: var(--theme-danger);
}
.assembly-issues {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  list-style: none;
  margin: 0;
  padding: 0;
}
.issue-chip {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-left-width: 3px;
  color: var(--theme-text-secondary);
  font-size: var(--type-body);
  padding: 0.35rem 0.5rem;
  text-align: left;
  width: 100%;
}
.issue-chip--error {
  border-left-color: var(--theme-danger);
}
.issue-chip--warning {
  border-left-color: var(--theme-warning);
}
.plan-angle {
  cursor: pointer;
  fill: var(--theme-text-primary);
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
}

.opening-palette {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--space-2);
}
.opening-choice--named,
.projects-page .opening-choice--named {
  border-radius: var(--r-2);
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  width: 100%;
  height: auto;
  gap: var(--space-2);
  padding: var(--space-2);
  text-align: left;
  font-size: var(--text-xs);
}
.opening-choice--named svg {
  width: 36px;
  height: 36px;
}
.opening-availability {
  margin-top: var(--space-2);
  font-size: var(--text-xs);
  color: var(--theme-text-secondary);
}
.plan-angle:hover {
  fill: var(--theme-accent);
}
.plan-coupling {
  cursor: pointer;
}
.plan-coupling.is-selected {
  stroke: var(--theme-accent);
}
.plan-coupling.has-issue {
  stroke: var(--theme-danger);
}
.plan-issue-flag {
  fill: var(--theme-danger);
  font-weight: 600;
}
.divider-grip {
  fill: var(--theme-text-muted);
  fill-opacity: 0.07;
  outline: none;
  pointer-events: all;
  touch-action: none;
}
.divider-grip.is-vertical {
  cursor: ew-resize;
}
.divider-grip.is-horizontal {
  cursor: ns-resize;
}
.divider-grip:hover,
.divider-grip:active {
  fill: var(--theme-accent);
  fill-opacity: 0.18;
  stroke: var(--theme-accent);
  stroke-width: 1.5;
  vector-effect: non-scaling-stroke;
}
.seam-grip {
  cursor: ew-resize;
  fill: var(--theme-text-muted);
  fill-opacity: 0.06;
  pointer-events: all;
  touch-action: none;
}
.seam-grip:hover {
  fill: var(--theme-accent);
  fill-opacity: 0.14;
}
.seam-grip-dot,
.divider-grip-dots circle {
  fill: var(--theme-text-muted);
  opacity: 0.55;
}
.seam-grip:hover ~ .seam-grip-dot,
.divider-grip:hover ~ .divider-grip-dots circle,
.divider-grip.is-selected ~ .divider-grip-dots circle {
  fill: var(--theme-accent);
  opacity: 1;
}
.divide-preview-line {
  pointer-events: none;
  stroke: var(--theme-accent);
  stroke-dasharray: 14 10;
  stroke-width: 2.5;
  vector-effect: non-scaling-stroke;
}
.front-module.is-divide-target {
  cursor: crosshair;
}
.seam-preview {
  pointer-events: none;
}
.seam-preview-line {
  stroke: var(--theme-accent);
  stroke-dasharray: 16 12;
  stroke-width: 3;
  vector-effect: non-scaling-stroke;
}
.seam-preview-label {
  fill: var(--theme-accent-ink);
  font-family: var(--font-mono);
  font-size: var(--type-display);
  font-variant-numeric: tabular-nums;
}
.assistant-panel__prompt {
  width: 100%;
  box-sizing: border-box;
  resize: vertical;
  border: 1px solid var(--theme-border-strong);
  border-radius: var(--radius-sm);
  background: var(--theme-surface);
  color: var(--theme-text-primary);
  font: inherit;
  padding: 6px 8px;
  margin-bottom: 8px;
}
.assistant-panel__preview,
.alternatives-panel__result {
  border-top: 1px solid var(--theme-border-subtle);
  margin-top: 8px;
  padding-top: 8px;
}
.assistant-panel__notes {
  color: var(--theme-text-secondary);
  font-size: var(--type-dense);
  margin: 0 0 6px;
}
.assistant-panel__ops,
.assistant-panel__rejected {
  margin: 0 0 8px;
  padding-left: 16px;
  font-size: var(--type-dense);
}
.assistant-panel__rejected {
  color: var(--theme-mark);
}
.assistant-panel__meta {
  color: var(--theme-text-muted);
  font-size: var(--type-micro);
  margin: 6px 0 0;
}
.alternatives-panel__cards {
  display: grid;
  gap: 8px;
  margin-bottom: 8px;
}
.alternative-card {
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-md);
  padding: 8px;
  background: var(--theme-surface);
}
.alternative-card__thumb {
  display: block;
  max-height: 140px;
}
.alternative-card__thumb svg,
.alternative-card__thumb .alternative-card__render {
  display: block;
  width: 100%;
  height: auto;
  min-height: 96px;
  border-radius: var(--radius-sm);
  background: var(--model3d-backdrop, var(--theme-bg-canvas));
}
.alternative-card__label {
  font-weight: 600;
  font-size: var(--type-dense);
  margin: 6px 0 2px;
}
.alternative-card__rationale {
  color: var(--theme-text-secondary);
  font-size: var(--type-micro);
  margin: 0 0 4px;
}
.alternative-card__metrics {
  color: var(--theme-text-muted);
  font-size: var(--type-micro);
  font-variant-numeric: tabular-nums;
  margin: 0;
}
.alternative-card__warnings {
  color: var(--theme-mark);
  font-size: var(--type-micro);
  margin: 4px 0 0;
}
.alternative-card__use {
  margin-top: 6px;
}
.context-menu {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-pop);
  display: flex;
  flex-direction: column;
  min-width: 200px;
  padding: 4px;
  position: fixed;
  z-index: var(--z-toast);
}
.context-menu__item {
  background: transparent;
  border: none;
  border-radius: var(--radius-sm);
  color: var(--theme-text-secondary);
  font: inherit;
  font-size: var(--type-body);
  padding: 7px 10px;
  text-align: left;
}
.context-menu__item:hover {
  background: var(--theme-surface-raised);
  color: var(--theme-text-primary);
}
.context-menu__item--assistant {
  border-top: 1px solid var(--theme-border-subtle);
  border-radius: 0 0 4px 4px;
  color: var(--theme-accent);
  margin-top: 4px;
}
.context-menu__item {
  align-items: center;
  display: flex;
  justify-content: space-between;
  gap: 12px;
}
.context-menu__label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.context-menu__hint {
  background: transparent;
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-xs, 3px);
  color: var(--theme-text-muted);
  font-family: var(--font-mono);
  font-size: var(--type-micro);
  padding: 1px 5px;
  white-space: nowrap;
}
.member-mullion.is-selected,
.member-coupler.is-selected {
  stroke: var(--theme-accent);
  stroke-width: 4;
}
.divider-grip.is-selected {
  fill: var(--theme-accent);
  fill-opacity: 0.22;
  stroke: var(--theme-accent);
  stroke-width: 1.5;
  vector-effect: non-scaling-stroke;
}
.joint-hit {
  cursor: pointer;
  fill: transparent;
  pointer-events: all;
}
.joint-hit:hover {
  fill: var(--theme-accent);
  fill-opacity: 0.14;
  stroke: var(--theme-accent);
  stroke-width: 1.5;
  vector-effect: non-scaling-stroke;
}
.split-dim,
.member-dim {
  fill: var(--theme-text-muted);
  font-family: var(--font-mono);
  font-size: var(--type-title-l);
  font-variant-numeric: tabular-nums;
  pointer-events: none;
  user-select: none;
}
.prov-strip {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  list-style: none;
  margin: 0 0 10px;
  padding: 0;
}
.prov-chip {
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--r-2);
  color: var(--theme-text-secondary);
  font-size: var(--type-micro);
  padding: 1px 8px 1px 3px;
  white-space: nowrap;
}
.prov-chip__state {
  border-radius: var(--r-2);
  font-size: var(--type-micro);
  font-weight: 600;
  letter-spacing: 0.04em;
  margin-right: 4px;
  padding: 1px 6px;
  text-transform: uppercase;
}
.prov-chip--verified .prov-chip__state {
  background: color-mix(in srgb, var(--theme-success) 16%, transparent);
  color: var(--theme-success);
}
.prov-chip--declared .prov-chip__state {
  background: color-mix(in srgb, var(--theme-accent) 14%, transparent);
  color: var(--theme-accent-ink);
}
.prov-chip--unknown .prov-chip__state {
  background: var(--theme-surface-raised);
  color: var(--theme-text-muted);
}
.prov-chip--blocked .prov-chip__state {
  background: color-mix(in srgb, var(--theme-danger) 14%, transparent);
  color: var(--theme-danger);
}
.division-children {
  list-style: none;
  margin: 4px 0 0;
  padding: 0;
}
.division-children li + li {
  margin-top: 2px;
}
.recents {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-top: 6px;
}
.recents__label {
  color: var(--theme-text-muted);
  font-size: var(--type-micro);
}
.recents__chip {
  background: var(--theme-surface-raised);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--r-2);
  color: var(--theme-text-secondary);
  font-family: var(--font-mono);
  font-size: var(--type-micro);
  max-width: 140px;
  overflow: hidden;
  padding: 2px 9px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.recents__chip:hover {
  border-color: var(--theme-accent);
  color: var(--theme-text-primary);
}
.recents__chip--favorite {
  border-color: color-mix(in srgb, var(--theme-accent) 40%, transparent);
  color: var(--theme-accent-strong, var(--theme-accent));
}
.assembly-field__row {
  align-items: center;
  display: flex;
  gap: 6px;
}
.assembly-field__row select {
  flex: 1;
  min-width: 0;
}
.star-toggle {
  background: transparent;
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--r-2);
  color: var(--theme-text-muted);
  flex: 0 0 auto;
  font-size: var(--type-title-m);
  line-height: 1;
  padding: 5px 7px;
}
.star-toggle:hover:not(:disabled),
.star-toggle.is-active {
  border-color: var(--theme-accent);
  color: var(--theme-accent);
}
.star-toggle:disabled {
  cursor: not-allowed;
  opacity: 0.4;
}
.issue-fix {
  background: transparent;
  border: none;
  color: var(--theme-accent);
  font-size: var(--type-micro);
  margin-top: 2px;
  padding: 0 4px;
  text-align: left;
}
.issue-fix:hover {
  text-decoration: underline;
}
.section-view {
  display: block;
  height: auto;
  margin-top: 0.5rem;
  width: 100%;
}
.section-member {
  fill: var(--member-pvc-fill);
  stroke: var(--member-pvc-edge);
  stroke-width: 0.6;
}
.section-member--aluminium {
  fill: var(--member-aluminium-fill);
  stroke: var(--member-aluminium-edge);
}
.section-member--approx {
  fill: none;
  stroke-dasharray: 3 2;
}
.section-glass {
  fill: var(--model3d-glass);
  opacity: 0.75;
}
.section-gasket {
  fill: var(--model3d-gasket);
}
.section-dim {
  stroke: var(--theme-text-muted);
  stroke-width: 0.5;
}
.section-dim__arrow {
  fill: var(--theme-text-muted);
}
.section-dim__text {
  fill: var(--theme-text-muted);
  font-size: var(--type-micro);
}
.section-label {
  fill: var(--theme-text-muted);
  font-size: var(--type-micro);
  letter-spacing: 0.12em;
}
.section-approx {
  fill: var(--theme-warning);
  font-size: var(--type-micro);
}
.section-break {
  fill: none;
  stroke: var(--theme-text-muted);
  stroke-width: 1.2;
}
.module-frameless .module-glass {
  stroke: var(--theme-border-strong);
}
.frameless-exposed {
  fill: var(--theme-bg-canvas);
  stroke: none;
  opacity: 0.35;
}
.frameless-channel {
  fill: var(--model3d-steel);
  stroke: var(--theme-text-muted);
  stroke-width: 1.2;
  vector-effect: non-scaling-stroke;
}
.frameless-clamp,
.frameless-fitting {
  fill: var(--model3d-steel);
  stroke: var(--theme-text-primary);
  stroke-width: 1.4;
  vector-effect: non-scaling-stroke;
}
.frameless-fitting--patch_fitting,
.frameless-fitting--clamp {
  fill: var(--member-aluminium-edge);
}
.frameless-fitting--hinge,
.frameless-fitting--lock {
  fill: var(--theme-text-secondary);
}
.frameless-seal {
  fill: none;
  stroke: var(--theme-text-muted);
  stroke-dasharray: 10 6;
  stroke-width: 1.4;
  vector-effect: non-scaling-stroke;
}
.sliding-track {
  stroke: var(--theme-text-muted);
  stroke-width: 1.6;
  stroke-dasharray: 7 5;
  vector-effect: non-scaling-stroke;
}
.sliding-arrow {
  fill: none;
  stroke: var(--theme-text-primary);
  stroke-width: 3;
  stroke-linecap: round;
  stroke-linejoin: round;
  vector-effect: non-scaling-stroke;
}

.hardware-panel {
  border-top: 1px solid var(--border-default);
  padding: var(--space-3) 0;
  color: var(--text-primary);
}
.hardware-panel h5,
.hardware-panel h6 {
  margin: 0 0 var(--space-2);
  font-size: var(--type-body);
  font-weight: 500;
}
.hardware-panel p {
  margin: var(--space-2) 0;
  overflow-wrap: anywhere;
}
.hardware-panel summary {
  cursor: pointer;
  padding: var(--space-2) 0;
  font-weight: 500;
}
.hardware-panel button {
  margin: var(--space-1) var(--space-1) var(--space-1) 0;
}
.assembly-inspector .hardware-panel button[type="button"] {
  border-radius: var(--r-1);
}
.assembly-inspector .hardware-panel .assembly-field input,
.assembly-inspector .hardware-panel select {
  border-radius: var(--r-1);
}
.hardware-class {
  display: grid;
  gap: var(--space-1);
}
.hardware-class span,
.hardware-source {
  color: var(--text-small-muted);
  font-size: var(--type-dense);
}
.hardware-demo {
  color: var(--text-small-muted);
  font-size: var(--type-dense);
  margin-left: var(--space-2);
}
.hardware-warning,
.hardware-proposal {
  border-left: 1px solid var(--border-default);
  padding: var(--space-2);
  background: var(--surface-panel);
}
.hardware-number,
.hardware-facts dd {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
}
.hardware-options {
  border: 0;
  margin: 0;
  padding: 0;
  display: grid;
  gap: var(--space-2);
}
.hardware-options label {
  display: flex;
  align-items: start;
  gap: var(--space-2);
}
.hardware-facts {
  margin: var(--space-2) 0;
}
.hardware-facts > div {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-2);
  padding: var(--space-1) 0;
}
.hardware-facts dd {
  margin: 0;
  text-align: right;
  overflow-wrap: anywhere;
}
.hardware-components {
  list-style: none;
  margin: 0;
  padding: 0;
}
.hardware-components > li {
  border-top: 1px solid var(--border-default);
  padding: var(--space-2) 0;
}
.hardware-components > li > div {
  display: flex;
  justify-content: space-between;
  align-items: start;
  gap: var(--space-2);
}
.hardware-components > li > div .hardware-number {
  flex: 0 0 auto;
}
.hardware-leaf + .hardware-leaf {
  border-top: 1px solid var(--border-default);
  padding-top: var(--space-2);
}

/* §15 profile section preview — true-scale cross-section with provenance. */
.section-preview {
  margin: 0;
  display: grid;
  gap: 0.35rem;
}

.section-preview svg {
  display: block;
  width: 100%;
  max-width: 180px;
  height: auto;
  border: 1px solid var(--line, #d8d8d8);
  border-radius: var(--radius-sm);
  background: var(--surface-raised, #fff);
}

.section-preview__shape {
  stroke-width: 0.6;
  vector-effect: non-scaling-stroke;
}

.section-preview__shape--approx {
  fill: none;
  stroke-dasharray: 3 2;
}

.section-preview__axis {
  stroke: var(--line-strong, #9a9a9a);
  stroke-width: 0.4;
  stroke-dasharray: 4 2;
  vector-effect: non-scaling-stroke;
}

.section-preview__axis-label,
.section-preview__dims {
  fill: var(--ink-3, #6b6b6b);
  font-family: var(--font-mono, monospace);
}

.section-preview figcaption {
  display: grid;
  gap: var(--space-1);
  font-size: var(--type-dense);
  color: var(--ink-3, #6b6b6b);
}

.section-preview[data-provenance="APPROXIMATE"] figcaption::before {
  content: "◌ ";
}

.section-preview[data-provenance="POLYGON"] figcaption::before,
.section-preview[data-provenance="DXF_REFERENCE"] figcaption::before {
  content: "■ ";
}

.section-preview-list {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
}

.finish-selector {
  background: var(--theme-surface);
  border: 1px solid var(--theme-border);
  border-radius: var(--radius-md);
  padding: var(--space-2) var(--space-3);
}

.projects-page .finish-selector button {
  border-radius: var(--r-1);
}

.finish-selector__row {
  display: flex;
  flex-wrap: wrap;
  align-items: end;
  gap: var(--space-3);
}

.finish-face {
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
  min-width: 0;
}

.finish-face > span:first-child,
.finish-price > span:first-child {
  color: var(--theme-text-muted);
  font-size: var(--text-xs);
}

.finish-face__control {
  display: flex;
  align-items: center;
  gap: var(--space-2);
}

.finish-swatch {
  display: inline-block;
  width: var(--space-6);
  height: var(--space-6);
  flex-shrink: 0;
  border: 1px solid var(--theme-border-strong);
  background-size: cover;
}

.finish-equal {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  min-height: var(--control-height);
}

.finish-price {
  margin-left: auto;
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
}

.finish-selector__notice,
.finish-source {
  font-size: var(--text-xs);
  margin: var(--space-2) 0 0;
}

.finish-source summary {
  cursor: pointer;
  min-height: var(--control-height);
}

.finish-source dl {
  display: grid;
  gap: var(--space-2);
  margin: var(--space-2) 0;
}

.finish-source dl > div {
  display: grid;
  grid-template-columns: minmax(0, 12rem) minmax(0, 1fr);
  gap: var(--space-3);
}

.finish-source dd {
  margin: 0;
  display: flex;
  align-items: center;
  gap: var(--space-2);
  overflow-wrap: anywhere;
}

.finish-number {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
}
